import unittest
from email.message import EmailMessage
from main import parse_message


class ParseTests(unittest.TestCase):
    def raw(self, body="Please reserve a table.", headers=""):
        return (
            "From: Noor <noor@example.invalid>\nSubject: Seat   request\nMessage-ID: <one@example.invalid>\n"
            + headers
            + "\n"
            + body
        ).encode()

    def test_plain_headers_and_body(self):
        m = parse_message(self.raw())
        self.assertEqual(
            (m["sender"], m["subject"], m["text"]),
            ("noor@example.invalid", "Seat request", "Please reserve a table."),
        )

    def test_multipart_prefers_plain_and_ignores_attachment(self):
        m = EmailMessage()
        m["From"] = "a@example.invalid"
        m.set_content("Plain evidence")
        m.add_alternative("<b>Different HTML</b>", subtype="html")
        m.add_attachment(
            b"Not the body", maintype="text", subtype="plain", filename="notes.txt"
        )
        self.assertEqual(parse_message(m.as_bytes())["text"], "Plain evidence")

    def test_html_only_requires_manual_review(self):
        m = EmailMessage()
        m["From"] = "a@example.invalid"
        m.set_content("<b>visible</b>", subtype="html")
        parsed = parse_message(m.as_bytes())
        self.assertEqual(parsed["text"], "")
        self.assertEqual(parsed["body_status"], "no-plain-body")

    def test_missing_id_is_stable_and_body_sensitive(self):
        raw = b"From: a@example.invalid\n\nA"
        a = parse_message(raw)
        self.assertEqual(a["id"], parse_message(raw)["id"])
        self.assertNotEqual(a["id"], parse_message(raw + b"B")["id"])

    def test_reference_ids_deduplicate(self):
        m = parse_message(
            self.raw(
                headers="References: <a@example.invalid> <b@example.invalid>\nIn-Reply-To: <b@example.invalid>\n"
            )
        )
        self.assertEqual(
            m["references"], ["<a@example.invalid>", "<b@example.invalid>"]
        )

    def test_empty_missing_sender_and_oversize_rejected(self):
        for raw in (b"", b"Subject: hi\n\nBody", b"x" * 1_000_001):
            with self.subTest(size=len(raw)), self.assertRaises(ValueError):
                parse_message(raw)

import unittest
from main import group_threads, triage


def msg(id, text="Please reserve the west table.", refs=None):
    return {
        "id": id,
        "sender": "a@example.invalid",
        "subject": "Same subject",
        "text": text,
        "references": refs or [],
        "body_status": "plain",
    }


class TriageTests(unittest.TestCase):
    def test_transitive_thread_and_unrelated_subject(self):
        result = group_threads(
            [msg("c", refs=["b"]), msg("x"), msg("b", refs=["a"]), msg("a")]
        )
        self.assertEqual([len(t["messages"]) for t in result], [3, 1])
        self.assertEqual(result[0]["id"], "a")

    def test_duplicate_and_conflicting_identity(self):
        self.assertEqual(len(group_threads([msg("a"), msg("a")])[0]["messages"]), 1)
        with self.assertRaises(ValueError):
            group_threads([msg("a"), msg("a", "Changed")])

    def test_cycles_and_missing_reference(self):
        self.assertEqual(
            len(group_threads([msg("a", refs=["b"]), msg("b", refs=["a", "missing"])])),
            1,
        )

    def test_action_evidence_uses_original_spans(self):
        m = msg("a", "Before: PLEASE reserve a chair.")
        d = triage(m)
        self.assertEqual(d["category"], "action")
        self.assertEqual(d["priority"], 0)
        for e in d["evidence"]:
            self.assertEqual(m["text"][e["start"] : e["end"]], e["quote"])

    def test_conflicts_and_unmatched_are_uncertain(self):
        self.assertEqual(
            triage(msg("a", "Please confirm. For your information, seats changed."))[
                "reason"
            ],
            "conflicting rules",
        )
        self.assertEqual(triage(msg("b", "A bench is here."))["category"], "uncertain")

    def test_word_boundary_and_invalid_rule(self):
        self.assertEqual(triage(msg("a", "I am displeased."))["category"], "uncertain")
        with self.assertRaises(ValueError):
            triage(msg("a"), {"action": [""]})
        with self.assertRaises(ValueError):
            triage(msg("a"), {"send": ["please"]})

    def test_custom_phrase_can_classify_information(self):
        d = triage(
            msg("a", "Inventory updated this morning."),
            {"information": ["inventory updated"]},
        )
        self.assertEqual(d["category"], "information")
        self.assertTrue(d["review_required"])

import io
import json
import unittest
from unittest.mock import patch
from email import policy
from email.parser import BytesParser
from main import build_draft, provider_proposal


def msg():
    return {
        "id": "<held@example.invalid>",
        "sender": "kai@example.invalid",
        "subject": "Bench labels",
        "text": "Please print two signs.\nUse green card.",
        "references": ["<parent@example.invalid>"],
        "body_status": "plain",
    }


def decision():
    return {
        "message_id": "<held@example.invalid>",
        "category": "action",
        "evidence": [{"quote": "Please", "start": 0, "end": 6}],
    }


class DraftTests(unittest.TestCase):
    def test_unsent_email_round_trips(self):
        d = build_draft(msg(), decision())
        parsed = BytesParser(policy=policy.default).parsebytes(d["eml"].encode())
        self.assertEqual(parsed["To"], "kai@example.invalid")
        self.assertEqual(parsed["X-Unsent"], "1")
        self.assertEqual(parsed["In-Reply-To"], "<held@example.invalid>")
        self.assertEqual(d["status"], "draft-only")

    def test_reply_contains_source_and_edit_placeholder(self):
        d = build_draft(msg(), decision())
        self.assertIn("Please print two signs.", d["body"])
        self.assertIn("[Write and check your response here.]", d["body"])

    def test_existing_reply_subject_not_duplicated(self):
        m = msg()
        m["subject"] = "Re: Bench labels"
        self.assertEqual(build_draft(m, decision())["subject"], m["subject"])

    def test_wrong_identity_and_fabricated_span_rejected(self):
        d = decision()
        d["message_id"] = "other"
        with self.assertRaises(ValueError):
            build_draft(msg(), d)
        d = decision()
        d["evidence"][0]["quote"] = "Urgent"
        with self.assertRaises(ValueError):
            build_draft(msg(), d)

    def test_provider_request_and_response_contract(self):
        raw = json.dumps(
            {
                "choices": [
                    {
                        "message": {
                            "content": json.dumps(
                                {"category": "action", "quote": "print two signs"}
                            )
                        }
                    }
                ]
            }
        ).encode()
        with patch("urllib.request.OpenerDirector.open", return_value=io.BytesIO(raw)) as opened:
            p = provider_proposal(
                msg(), "http://localhost:1234/v1/chat/completions", "test-model"
            )
            request = opened.call_args.args[0]
            payload = json.loads(request.data)
            self.assertEqual(payload["model"], "test-model")
            self.assertEqual(payload["messages"][1]["content"], msg()["text"])
            self.assertEqual(request.get_method(), "POST")
            self.assertTrue(p["review_required"])

    def test_provider_fabrication_and_endpoint_rejected(self):
        raw = json.dumps(
            {
                "choices": [
                    {
                        "message": {
                            "content": json.dumps(
                                {"category": "action", "quote": "Send money"}
                            )
                        }
                    }
                ]
            }
        ).encode()
        with (
            patch("urllib.request.OpenerDirector.open", return_value=io.BytesIO(raw)),
            self.assertRaises(ValueError),
        ):
            provider_proposal(msg(), "https://example.invalid/chat", "m")
        with self.assertRaises(ValueError):
            provider_proposal(msg(), "file:///tmp/data", "m")

