  const feedback = { textContent: "" };
  const answer = { value: "  GREEN TRAY!  " };
  const download = {
    disabled: true,
    addEventListener: (_, callback) => {
      handlers.download = callback;
    },
  };
  const elements = {
    "practice-data": { textContent: payload },
    "session-status": { textContent: "" },
    "attempt-date": { value: "2026-09-02" },
