import { readFileSync, writeFileSync } from "node:fs";
import { parseArgs } from "node:util";
import { parseTrace, analyze, render } from "./main.ts";
import { fromOTLP } from "./otlp.ts";
const { values } = parseArgs({
  options: {
    input: { type: "string" },
    format: { type: "string", default: "jsonl" },
    baseline: { type: "string" },
    output: { type: "string", default: "trace.html" },
    json: { type: "string" },
  },
});
if (!values.input)
  throw new Error(
    "Usage: node cli.ts --input samples/trace.jsonl [--baseline samples/before.jsonl] --output trace.html",
  );
if (!["jsonl", "otlp"].includes(values.format!))
  throw new Error("format must be jsonl or otlp");
const spans = parseTrace(
  values.format === "otlp"
    ? fromOTLP(JSON.parse(readFileSync(values.input, "utf8")))
        .map((x) => JSON.stringify(x))
        .join("\n")
    : readFileSync(values.input, "utf8"),
);
const report: any = { schema_version: 1, ...analyze(spans) };
if (values.baseline) {
  const old = analyze(parseTrace(readFileSync(values.baseline, "utf8")));
  report.comparison = {
    wall_time_delta_ms: report.wallTime - old.wallTime,
    token_delta: report.totalTokens - old.totalTokens,
    error_delta: report.errors.length - old.errors.length,
  };
}
writeFileSync(values.output!, render(spans));
if (values.json)
  writeFileSync(values.json, JSON.stringify(report, null, 2) + "\n");
console.log(JSON.stringify({ ...report, artifact: values.output }, null, 2));

export type Span = {
  id: string;
  parent?: string;
  name: string;
  start: number;
  end: number;
  status: "ok" | "error";
  tokens: number;
};
import { pathToFileURL } from "node:url";
import path from "node:path";

export function parseTrace(raw: string): any[] {
  throw new Error("Not implemented: parseTrace");
}
export function validateTree(spans: Span[]): any {
  throw new Error("Not implemented: validateTree");
}
export function unionDuration(intervals: [number, number][]): number {
  throw new Error("Not implemented: unionDuration");
}
export function analyze(spans: Span[]): any {
  throw new Error("Not implemented: analyze");
}
export function render(spans: Span[]): string {
  throw new Error("Not implemented: render");
}

import type { Span } from "./main.ts";
export function fromOTLP(payload: any): Span[] {
  const spans = (payload.resourceSpans ?? []).flatMap((resource: any) =>
    (resource.scopeSpans ?? []).flatMap((scope: any) => scope.spans ?? []),
  );
  if (!spans.length) return [];
  const epoch = spans.reduce((min: bigint, span: any) => {
    const value = BigInt(span.startTimeUnixNano);
    return value < min ? value : min;
  }, BigInt(spans[0].startTimeUnixNano));
  return spans.map((span: any) => {
    const attrs = Object.fromEntries(
      (span.attributes ?? []).map((a: any) => [
        a.key,
        a.value?.intValue ?? a.value?.doubleValue ?? a.value?.stringValue,
      ]),
    );
    const key = (id: string) => span.traceId + ":" + id;
    const parent = span.parentSpanId ? key(span.parentSpanId) : undefined;
    return {
      id: key(span.spanId),
      ...(parent ? { parent } : {}),
      name: span.name,
      start: Number(BigInt(span.startTimeUnixNano) - epoch) / 1e6,
      end: Number(BigInt(span.endTimeUnixNano) - epoch) / 1e6,
      status: span.status?.code === 2 ? "error" : "ok",
      tokens:
        Number(attrs["gen_ai.usage.input_tokens"] ?? 0) +
        Number(attrs["gen_ai.usage.output_tokens"] ?? 0),
    };
  });
}

