            .get(1)
            .ok_or(Error::Limit)?
            .parse::<u32>()
            .map_err(|_| Error::Limit)?;
        let selected = select(&request, &profiles(), budget)?;
        plan(&request, &selected)
    })();
    match result {
        Ok(out) => print!("{}", out),
        Err(e) => {
            eprintln!("{:?}", e);
            std::process::exit(1)
        }
    }
}

