import { readFileSync, writeFileSync } from "node:fs";
import { parseArgs } from "node:util";
import { fileURLToPath } from "node:url";
import { execFileSync } from "node:child_process";
import {
  FixtureDriver,
  GstackDriver,
  runAgent,
  parseObservation,
} from "./main.ts";
const { values } = parseArgs({
  options: {
    task: { type: "string" },
    live: { type: "boolean" },
    output: { type: "string", default: "browser-run.json" },
    screenshot: { type: "string", default: "browser-result.png" },
  },
});
if (!values.task) throw new Error("--task samples/contact.json is required");
const config = JSON.parse(readFileSync(values.task, "utf8"));
let driver;
if (values.live) {
  const url = new URL(config.url);
  if (
    url.origin !== config.task.allowedOrigin ||
    !["127.0.0.1", "localhost", "[::1]"].includes(url.hostname)
  )
    throw new Error(
      "live lab only navigates an explicitly allowed loopback fixture",
    );
  const binary = process.env.BROWSE_BIN;
  if (!binary) throw new Error("BROWSE_BIN is required for live Chromium");
  execFileSync(binary, ["goto", url.href], {
    timeout: 20000,
    encoding: "utf8",
  });
  driver = new GstackDriver(binary, values.screenshot!);
} else {
  driver = new FixtureDriver(
    fileURLToPath(new URL("./success.png", import.meta.url)),
  );
  if (config.observation)
    driver.observation = parseObservation(config.observation);
}
const result = {
  schema_version: 1,
  mode: values.live
    ? "live Chromium"
    : "fixture transitions with recorded success pixels",
  ...(await runAgent(driver, config.task, config.max_steps ?? 8)),
};
writeFileSync(values.output!, JSON.stringify(result, null, 2) + "\n");
console.log(JSON.stringify(result, null, 2));
if (result.status !== "complete") process.exitCode = 2;

export type Field = {
  id: string;
  label: string;
  value: string;
  disabled: boolean;
};
export type Button = {
  id: string;
  label: string;
  disabled: boolean;
  dangerous: boolean;
};
export type Observation = {
  url: string;
  fields: Field[];
  buttons: Button[];
  done: boolean;
};
export type Task = {
  name: string;
  email: string;
  allowedOrigin: string;
  fields?: { label: string; value: string }[];
  submitLabel?: string;
};
export type Action =
  | { kind: "fill"; id: string; value: string }
  | { kind: "click"; id: string }
  | { kind: "done" }
  | { kind: "blocked"; reason: string };
export type Driver = {
  observe: () => Promise<Observation>;
  act: (action: Action) => Promise<void>;
  capture: () => Promise<string>;
};

import { pathToFileURL } from "node:url";
import path from "node:path";

export function parseObservation(raw: unknown): any {
  throw new Error("Not implemented: parseObservation");
}
export function choose(observation: Observation, task: Task): any {
  throw new Error("Not implemented: choose");
}
export function inspectPNG(file: string): any {
  throw new Error("Not implemented: inspectPNG");
}
export async function runAgent(
  driver: Driver,
  task: Task,
  maxSteps = 5,
): Promise<any> {
  throw new Error("Not implemented: runAgent");
}
export class FixtureDriver implements Driver {
  observation!: Observation;
  screenshot: string;
  actions: Action[] = [];
  constructor(screenshot: string) {
    this.screenshot = screenshot;
  }
  async observe(): Promise<Observation> {
    throw new Error("Not implemented: fixture observation");
  }
  async act(action: Action): Promise<void> {
    throw new Error("Not implemented: fixture transition");
  }
  async capture(): Promise<string> {
    throw new Error("Not implemented: fixture capture");
  }
}
export class GstackDriver {
  constructor(
    binary: string,
    screenshot: string,
    invoke?: (args: string[]) => string,
  ) {}
  async observe(): Promise<any> {
    throw new Error("Not implemented: observe");
  }
  async act(action: Action): Promise<void> {
    throw new Error("Not implemented: act");
  }
  async capture(): Promise<string> {
    throw new Error("Not implemented: capture");
  }
}
export function scoreRuns(statuses: string[]): any {
  throw new Error("Not implemented: scoreRuns");
}

