//go:build !linux && !darwin

package main

import "fmt"

func withLedgerLock(_ string, _ func() error) error {
	return fmt.Errorf("the composed ledger requires Linux or macOS advisory file locks")
}

//go:build linux || darwin

package main

import (
	"os"
	"path/filepath"
	"syscall"
)

func withLedgerLock(directory string, run func() error) error {
	file, err := os.OpenFile(filepath.Join(directory, "ledger.lock"), os.O_CREATE|os.O_RDWR, 0600)
	if err != nil {
		return err
	}
	defer file.Close()
	if err = syscall.Flock(int(file.Fd()), syscall.LOCK_EX); err != nil {
		return err
	}
	defer syscall.Flock(int(file.Fd()), syscall.LOCK_UN)
	return run()
}

package main

import (
	"context"
	"encoding/json"
	"flag"
	"fmt"
	"os"
	"os/exec"
	"time"
)

func output(value any) error {
	encoder := json.NewEncoder(os.Stdout)
	encoder.SetIndent("", "  ")
	return encoder.Encode(value)
}
func runCLI() error {
	if len(os.Args) < 2 {
		return fmt.Errorf("usage: farm init|worker|run|status|demo [flags]")
	}
	command := os.Args[1]
	flags := flag.NewFlagSet(command, flag.ContinueOnError)
	directory := flags.String("store", "farm-data", "persistent same-host directory")
	input := flags.String("input", "samples/cases.json", "recorded prediction JSON array")
	shards := flags.Int("shards", 4, "fixed partition count")
	workers := flags.Int("workers", 2, "maximum concurrent worker processes")
	worker := flags.String("worker-id", "manual-worker", "lease owner")
	now := flags.Int64("now-ms", -1, "logical test clock; default is wall-clock milliseconds")
	ttl := flags.Int64("lease-ms", 30000, "claim duration")
	delay := flags.Int64("delay-ms", 0, "injected delay after claim for failure experiments")
	crash := flags.Bool("crash-after-claim", false, "abruptly exit86 after durable claim")
	if err := flags.Parse(os.Args[2:]); err != nil {
		return err
	}
	if flags.NArg() != 0 || *now < -1 || *delay < 0 || *delay > 60000 {
		return ErrInvalid
	}
	if command == "demo" {
		return demoFarm(*input, *shards, *workers)
	}
	if command == "init" || command == "run" {
		var cases []EvalCase
		if err := readJSON(*input, &cases); err != nil {
			return err
		}
		if err := InitFarm(*directory, cases, *shards); err != nil {
			return err
		}
	}
	switch command {
	case "init", "status":
		value, err := FarmStatus(*directory)
		if err != nil {
			return err
		}
		return output(value)
	case "worker":
		clock := func() int64 { return time.Now().UnixMilli() }
		if *now >= 0 {
			clock = func() int64 { return *now }
		}
		value, err := WorkShard(*directory, WorkerOptions{*worker, clock, *ttl, time.Duration(*delay) * time.Millisecond, *crash})
		if err != nil {
			return err
		}
		return output(value)
	case "run":
		ctx, cancel := context.WithTimeout(context.Background(), 2*time.Minute)
		defer cancel()
		value, err := RunFarm(ctx, *directory, *workers, *now, *ttl, *delay)
		if err != nil {
			return err
		}
		if err = output(value); err != nil {
			return err
		}
		if !value["complete"].(bool) {
			return fmt.Errorf("run pending: active unexpired leases; retry after expiry")
		}
		return nil
	default:
		return fmt.Errorf("unknown command %s", command)
	}
}
func demoFarm(input string, shards, workers int) error {
	directory, err := os.MkdirTemp("", "eval-farm-demo-")
	if err != nil {
		return err
	}
	defer os.RemoveAll(directory)
	var cases []EvalCase
	if err = readJSON(input, &cases); err != nil {
		return err
	}
	if err = InitFarm(directory, cases, shards); err != nil {
		return err
	}
	executable, err := os.Executable()
	if err != nil {
		return err
	}
	child := exec.Command(executable, "worker", "--store", directory, "--worker-id", "lost-worker", "--now-ms", "100", "--lease-ms", "10", "--crash-after-claim")
	raw, err := child.CombinedOutput()
	fmt.Print(string(raw))
	exit, crashed := err.(*exec.ExitError)
	if !crashed || exit.ExitCode() != 86 {
		return fmt.Errorf("expected crash exit86, received %v", err)
	}
	before, err := FarmStatus(directory)
	if err != nil {
		return err
	}
	if err = output(map[string]any{"phase": "after_worker_crash", "snapshot": before}); err != nil {
		return err
	}
	ctx, cancel := context.WithTimeout(context.Background(), 2*time.Minute)
	defer cancel()
	after, err := RunFarm(ctx, directory, workers, 110, 30, 0)
	if err != nil {
		return err
	}
	return output(map[string]any{"phase": "after_recovery", "snapshot": after})
}
func main() {
	if err := runCLI(); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
}

package main

import (
	"bytes"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
)

type EvalCase struct {
	ID       string `json:"id"`
	Prompt   string `json:"prompt"`
	Expected string `json:"expected"`
	Response string `json:"response"`
}
type FarmShard struct {
	Lease   Lease    `json:"lease"`
	CaseIDs []string `json:"case_ids"`
}
type Farm struct {
	SchemaVersion int         `json:"schema_version"`
	DatasetSHA256 string      `json:"dataset_sha256"`
	ShardCount    int         `json:"shard_count"`
	Cases         []EvalCase  `json:"cases"`
	Shards        []FarmShard `json:"shards"`
}
type CaseResult struct {
	ID      string `json:"id"`
	Correct bool   `json:"correct"`
}
type ShardResult struct {
	WorkerPID int          `json:"worker_pid"`
	Cases     []CaseResult `json:"cases"`
	Correct   int          `json:"correct"`
	Total     int          `json:"total"`
}

func readJSON(file string, value any) error {
	f, err := os.Open(file)
	if err != nil {
		return err
	}
	defer f.Close()
	raw, err := io.ReadAll(io.LimitReader(f, 4*1024*1024+1))
	if err != nil {
		return err
	}
	if len(raw) > 4*1024*1024 {
		return ErrLimit
	}
	decoder := json.NewDecoder(bytes.NewReader(raw))
	decoder.DisallowUnknownFields()
	if err = decoder.Decode(value); err != nil {
		return err
	}
	var extra any
	if decoder.Decode(&extra) != io.EOF {
		return ErrInvalid
	}
	return nil
}
func writeFarm(directory string, farm Farm) error {
	raw, err := json.MarshalIndent(farm, "", "  ")
	if err != nil {
		return err
	}
	if len(raw) > 4*1024*1024 {
		return ErrLimit
	}
	file, err := os.CreateTemp(directory, ".farm-*")
	if err != nil {
		return err
	}
	name := file.Name()
	defer os.Remove(name)
	if _, err = file.Write(append(raw, '\n')); err == nil {
		err = file.Sync()
	}
	closeErr := file.Close()
	if err != nil {
		return err
	}
	if closeErr != nil {
		return closeErr
	}
	return os.Rename(name, filepath.Join(directory, "farm.json"))
}
func caseDigest(cases []EvalCase) string {
	raw, _ := json.Marshal(cases)
	digest := sha256.Sum256(raw)
	return hex.EncodeToString(digest[:])
}
func validateCases(cases []EvalCase, shards int) ([][]string, error) {
	if len(cases) == 0 || len(cases) > 10000 {
		return nil, ErrInvalid
	}
	ids := make([]string, len(cases))
	for i, c := range cases {
		if len(c.ID) > 256 || len(c.Prompt) > 100000 || c.Expected == "" || len(c.Expected) > 100000 || len(c.Response) > 100000 {
			return nil, ErrInvalid
		}
		ids[i] = c.ID
	}
	return Partition(ids, shards)
}
func validateFarm(farm Farm) error {
	parts, err := validateCases(farm.Cases, farm.ShardCount)
	if err != nil {
		return err
	}
	if farm.SchemaVersion != 1 || farm.DatasetSHA256 != caseDigest(farm.Cases) {
		return ErrConflict
	}
	active := 0
	for index, ids := range parts {
		if len(ids) == 0 {
			continue
		}
		if active >= len(farm.Shards) {
			return ErrInvalid
		}
		s := farm.Shards[active]
		active++
		if s.Lease.Shard != fmt.Sprintf("shard-%d", index) || len(ids) != len(s.CaseIDs) {
			return ErrInvalid
		}
		for i, id := range ids {
			if s.CaseIDs[i] != id {
				return ErrConflict
			}
		}
		l := s.Lease
		if l.Version < 0 || l.Until < 0 || (l.Worker == "" && (l.Version != 0 || l.Until != 0 || l.Done || l.Result != "")) || (l.Worker != "" && (l.Version < 1 || l.Until <= 0)) {
			return ErrInvalid
		}
		if l.Done {
			var receipt ShardResult
			if err = json.Unmarshal([]byte(l.Result), &receipt); err != nil {
				return err
			}
			if receipt.Total != len(ids) || receipt.WorkerPID <= 0 || len(receipt.Cases) != len(ids) {
				return ErrInvalid
			}
			correct := 0
			for i, result := range receipt.Cases {
				if result.ID != ids[i] {
					return ErrConflict
				}
				if result.Correct {
					correct++
				}
			}
			if receipt.Correct != correct {
				return ErrConflict
			}
		} else if l.Result != "" {
			return ErrInvalid
		}
	}
	if active != len(farm.Shards) {
		return ErrInvalid
	}
	return nil
}
func loadFarm(directory string) (Farm, error) {
	var farm Farm
	if err := readJSON(filepath.Join(directory, "farm.json"), &farm); err != nil {
		return farm, err
	}
	return farm, validateFarm(farm)
}
func InitFarm(directory string, cases []EvalCase, shards int) error {
	parts, err := validateCases(cases, shards)
	if err != nil {
		return err
	}
	if err = os.MkdirAll(directory, 0700); err != nil {
		return err
	}
	return withLedgerLock(directory, func() error {
		current, err := loadFarm(directory)
		if err == nil {
			if current.DatasetSHA256 == caseDigest(cases) && current.ShardCount == shards {
				return nil
			}
			return fmt.Errorf("%w: dataset or shard count changed; choose a new store", ErrConflict)
		}
		if !errors.Is(err, os.ErrNotExist) {
			return err
		}
		farm := Farm{SchemaVersion: 1, DatasetSHA256: caseDigest(cases), ShardCount: shards, Cases: cases, Shards: []FarmShard{}}
		for i, ids := range parts {
			if len(ids) > 0 {
				farm.Shards = append(farm.Shards, FarmShard{Lease: Lease{Shard: fmt.Sprintf("shard-%d", i)}, CaseIDs: ids})
			}
		}
		return writeFarm(directory, farm)
	})
}
func ClaimShard(directory, worker string, now, ttl int64) (*FarmShard, []EvalCase, error) {
	var claimed *FarmShard
	var cases []EvalCase
	err := withLedgerLock(directory, func() error {
		farm, err := loadFarm(directory)
		if err != nil {
			return err
		}
		for i := range farm.Shards {
			s := &farm.Shards[i]
			if s.Lease.Done || (s.Lease.Worker != "" && now < s.Lease.Until) {
				continue
			}
			if err = Acquire(&s.Lease, worker, now, ttl); err != nil {
				return err
			}
			copy := *s
			claimed = &copy
			byID := map[string]EvalCase{}
			for _, c := range farm.Cases {
				byID[c.ID] = c
			}
			for _, id := range s.CaseIDs {
				cases = append(cases, byID[id])
			}
			return writeFarm(directory, farm)
		}
		return nil
	})
	return claimed, cases, err
}
func CompleteShard(directory string, claim FarmShard, now int64, result ShardResult) error {
	return withLedgerLock(directory, func() error {
		farm, err := loadFarm(directory)
		if err != nil {
			return err
		}
		raw, err := json.Marshal(result)
		if err != nil {
			return err
		}
		for i := range farm.Shards {
			l := &farm.Shards[i].Lease
			if l.Shard == claim.Lease.Shard {
				if err = Submit(l, claim.Lease.Worker, claim.Lease.Version, now, string(raw)); err != nil {
					return err
				}
				if err = validateFarm(farm); err != nil {
					return err
				}
				return writeFarm(directory, farm)
			}
		}
		return ErrInvalid
	})
}
func FarmStatus(directory string) (map[string]any, error) {
	var farm Farm
	err := withLedgerLock(directory, func() error {
		var err error
		farm, err = loadFarm(directory)
		return err
	})
	if err != nil {
		return nil, err
	}
	completed, correct, total := 0, 0, 0
	pids := map[int]bool{}
	receipts := []ShardResult{}
	for _, s := range farm.Shards {
		if s.Lease.Done {
			var receipt ShardResult
			json.Unmarshal([]byte(s.Lease.Result), &receipt)
			receipts = append(receipts, receipt)
			completed++
			correct += receipt.Correct
			total += receipt.Total
			pids[receipt.WorkerPID] = true
		}
	}
	return map[string]any{"schema_version": 1, "dataset_sha256": farm.DatasetSHA256, "complete": completed == len(farm.Shards), "completed_shards": completed, "active_shards": len(farm.Shards), "correct": correct, "evaluated": total, "dataset_cases": len(farm.Cases), "worker_processes": len(pids), "shards": farm.Shards, "receipts": receipts, "scope": "same-host POSIX processes evaluating supplied recorded predictions"}, nil
}

package main

import "errors"

var ErrInvalid = errors.New("invalid input")
var ErrLimit = errors.New("budget exceeded")
var ErrConflict = errors.New("conflict")

type Lease struct {
	Shard   string
	Worker  string
	Version int
	Until   int64
	Result  string
	Done    bool
}
type Item struct {
	ID    string
	Value string
}

package main

import (
	"context"
	"encoding/json"
	"fmt"
	"os"
	"os/exec"
	"strconv"
	"strings"
	"time"
)

type WorkerOptions struct {
	Worker          string
	Now             func() int64
	LeaseMS         int64
	Delay           time.Duration
	CrashAfterClaim bool
}

func normalized(text string) string { return strings.ToLower(strings.Join(strings.Fields(text), " ")) }
func WorkShard(directory string, options WorkerOptions) (map[string]any, error) {
	if options.Worker == "" || options.Now == nil || options.LeaseMS <= 0 || options.Delay < 0 || options.Delay > time.Minute {
		return nil, ErrInvalid
	}
	claim, cases, err := ClaimShard(directory, options.Worker, options.Now(), options.LeaseMS)
	if err != nil {
		return nil, err
	}
	if claim == nil {
		return map[string]any{"claimed": false, "worker_pid": os.Getpid()}, nil
	}
	if options.CrashAfterClaim {
		fmt.Printf("{\"crash_after\":\"claim\",\"shard\":%q,\"version\":%d}\n", claim.Lease.Shard, claim.Lease.Version)
		os.Exit(86)
	}
	time.Sleep(options.Delay)
	receipt := ShardResult{WorkerPID: os.Getpid(), Cases: []CaseResult{}, Total: len(cases)}
	for _, c := range cases {
		correct := normalized(c.Expected) == normalized(c.Response)
		receipt.Cases = append(receipt.Cases, CaseResult{c.ID, correct})
		if correct {
			receipt.Correct++
		}
	}
	if err = CompleteShard(directory, *claim, options.Now(), receipt); err != nil {
		return nil, fmt.Errorf("completion fenced for %s v%d: %w", claim.Lease.Shard, claim.Lease.Version, err)
	}
	return map[string]any{"claimed": true, "shard": claim.Lease.Shard, "worker_pid": os.Getpid(), "version": claim.Lease.Version, "correct": receipt.Correct, "total": receipt.Total}, nil
}
func RunFarm(ctx context.Context, directory string, workers int, now, ttl, delay int64) (map[string]any, error) {
	if workers < 1 || workers > 64 || now < -1 || ttl <= 0 || delay < 0 || delay > 60000 {
		return nil, ErrInvalid
	}
	executable, err := os.Executable()
	if err != nil {
		return nil, err
	}
	status, err := FarmStatus(directory)
	if err != nil {
		return nil, err
	}
	waves := status["active_shards"].(int)
	events := []json.RawMessage{}
	for wave := 0; wave < waves && !status["complete"].(bool); wave++ {
		ids := make([]string, workers)
		for i := range ids {
			ids[i] = fmt.Sprintf("worker-%d", i+1)
		}
		items, err := Parallel(ctx, ids, workers, func(ctx context.Context, id string) (string, error) {
			args := []string{"worker", "--store", directory, "--worker-id", id, "--now-ms", strconv.FormatInt(now, 10), "--lease-ms", strconv.FormatInt(ttl, 10), "--delay-ms", strconv.FormatInt(delay, 10)}
			raw, err := exec.CommandContext(ctx, executable, args...).CombinedOutput()
			if err != nil {
				return "", fmt.Errorf("%s: %w: %s", id, err, raw)
			}
			return string(raw), nil
		})
		if err != nil {
			return nil, err
		}
		progress := false
		for _, item := range items {
			var event struct {
				Claimed bool `json:"claimed"`
			}
			if err = json.Unmarshal([]byte(item.Value), &event); err != nil {
				return nil, err
			}
			progress = progress || event.Claimed
			events = append(events, json.RawMessage(item.Value))
		}
		status, err = FarmStatus(directory)
		if err != nil {
			return nil, err
		}
		if !progress {
			break
		}
	}
	status["worker_events"] = events
	return status, nil
}

