func TestOnce(t *testing.T) {
	v, e := Partition([]string{"a", "b", "c"}, 2)
	if e != nil || len(v[0])+len(v[1]) != 3 {
		t.Fatal(v, e)
	}
}
func TestDeterministic(t *testing.T) {
	a, _ := Partition([]string{"a"}, 3)
